<?php
declare(strict_types=1);require_once __DIR__.'/../config/api.php';$u=requireUser($pdo);if($_SERVER['REQUEST_METHOD']==='GET'){$s=$pdo->prepare('SELECT id,type,title,message,data_json,read_at,created_at FROM notifications WHERE user_id=? ORDER BY created_at DESC LIMIT 100');$s->execute([$u['user_id']]);respond(['success'=>true,'data'=>$s->fetchAll(PDO::FETCH_ASSOC)]);}if($_SERVER['REQUEST_METHOD']==='POST'){$d=jsonInput();$id=(int)($d['id']??0);if($id<=0)respond(['success'=>false,'message'=>'id is required'],422);$s=$pdo->prepare('UPDATE notifications SET read_at=COALESCE(read_at,UTC_TIMESTAMP()) WHERE id=? AND user_id=?');$s->execute([$id,$u['user_id']]);respond(['success'=>true,'message'=>'Notification marked as read']);}respond(['success'=>false,'message'=>'Method not allowed'],405);
